import 'package:flutter/material.dart';
import '../core/api.dart';
import '../core/session.dart';

class ProfilePage extends StatefulWidget { const ProfilePage({super.key}); @override State<ProfilePage> createState()=>_ProfilePageState(); }
class _ProfilePageState extends State<ProfilePage>{ Map<String,dynamic>? user; String? error; bool loading=true; @override void initState(){super.initState();_load();} Future<void>_load()async{try{final d=await HadirApi(token:await HadirSession().token()).me();final raw=d['user'] is Map?d['user']:d;if(mounted)setState(()=>user=Map<String,dynamic>.from(raw as Map));}catch(e){if(mounted)setState(()=>error=HadirApi.errorMessage(e));}finally{if(mounted)setState(()=>loading=false);}} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('الملف الشخصي')),body:loading?const Center(child:CircularProgressIndicator()):error!=null?Center(child:Text(error!)):RefreshIndicator(onRefresh:_load,child:ListView(padding:const EdgeInsets.all(20),children:[const CircleAvatar(radius:42,child:Icon(Icons.person,size:48)),const SizedBox(height:18),Center(child:Text('${user?['name']??'الموظف'}',style:const TextStyle(fontSize:25,fontWeight:FontWeight.bold))),const SizedBox(height:24),Card(child:Column(children:[ListTile(leading:const Icon(Icons.badge_outlined),title:const Text('رقم الموظف'),subtitle:Text('${user?['username']??user?['jobNumber']??'—'}')),const Divider(height:1),const ListTile(leading:Icon(Icons.security_outlined),title:Text('الدور'),subtitle:Text('موظف'))])),const SizedBox(height:16),const Card(child:ListTile(leading:Icon(Icons.phone_android),title:Text('الجهاز'),subtitle:Text('مرتبط بحساب الموظف')))])));
}
